    from pymatgen.analysis.defects.generators import VacancyGenerator
    from pymatgen.analysis.defects.core import get_vacancy
    from pathlib import Path

    results = {
        "defect_type": None,
        "replaced_atoms_set_1": None,
        "replaced_atoms_set_2": None
    }

    try:
        # Load the GaN structure
        file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")
        gan_struct = Structure.from_file(file_path / "GaN.vasp")

        # Generate all native defects
        defects = list(generate_all_native_defects(gan_struct))

        # Check if all defects are of type Substitution
        results["defect_type"] = all(isinstance(defect, Substitution) for defect in defects)

        # Check replaced atoms for substitution set 1
        substitution_1 = {"Ga": ["Mg", "Ca"]}
        replaced_atoms_1 = set()
        for defect in defects:
            if isinstance(defect, Substitution):
                original_species = defect.defect_site.specie.symbol
                if original_species in substitution_1:
                    replaced_atoms_1.add(original_species)
        results["replaced_atoms_set_1"] = replaced_atoms_1

        # Check replaced atoms for substitution set 2
        substitution_2 = {"Ga": "Mg"}
        replaced_atoms_2 = set()
        for defect in defects:
            if isinstance(defect, Substitution):
                original_species = defect.defect_site.specie.symbol
                if original_species in substitution_2:
                    replaced_atoms_2.add(original_species)
        results["replaced_atoms_set_2"] = replaced_atoms_2

    except Exception as e:
        # If any error occurs, set the corresponding result to None
        results["defect_type"] = None
        results["replaced_atoms_set_1"] = None
        results["replaced_atoms_set_2"] = None

    return results

